/**
 * Auto-generated icon-name constants: one per icon, for call sites that prefer
 * a named import over a bare string literal.
 * DO NOT EDIT MANUALLY: regenerated by the sync from NVIDIA's internal
 * monorepo (see CONTRIBUTING.md).
 *
 * @module iconTypes
 *
 * @example
 * ```tsx
 * import { ADD, GPU } from "@nvidia/gui-icons/iconTypes";
 * import { NvidiaGuiIcon } from "@nvidia/react-gui-icons";
 *
 * <NvidiaGuiIcon iconName={ADD} />
 * <NvidiaGuiIcon iconName={GPU} />
 * ```
 *
 * A name that starts with a digit is not a valid identifier, so those
 * constants carry an `ICON_` prefix:
 *
 * ```tsx
 * import { ICON_3D_AXIS } from "@nvidia/gui-icons/iconTypes";
 *
 * <NvidiaGuiIcon iconName={ICON_3D_AXIS} /> // "3d-axis"
 * ```
 */

